const fmt = new Intl.NumberFormat('es-CL');
const fmt1 = new Intl.NumberFormat('es-CL', { maximumFractionDigits: 1, minimumFractionDigits: 1 });
const money = v => '$' + fmt.format(v);
const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const idxOf = y => POP.years.indexOf(y);
const IDX_2024 = idxOf(2024);

/* ---------------- Pestañas ---------------- */
const tabs = [...document.querySelectorAll('[role="tab"]')];
const panels = [...document.querySelectorAll('[role="tabpanel"]')];
const ids = panels.map(p => p.id);

function showTab(id, { focus = false, scroll = true } = {}) {
  if (!ids.includes(id)) id = 'inicio';
  tabs.forEach(t => {
    const on = t.dataset.tab === id;
    t.setAttribute('aria-selected', on);
    t.tabIndex = on ? 0 : -1;
    if (on) {
      if (focus) t.focus();
      t.scrollIntoView({ block: 'nearest', inline: 'center', behavior: reduceMotion ? 'auto' : 'smooth' });
    }
  });
  panels.forEach(p => (p.hidden = p.id !== id));
  if (location.hash.slice(1) !== id) history.replaceState(null, '', '#' + id);
  pauseAll();
  renderNext(id);
  initCharts(id);
  initPlayers(id);
  if (scroll) window.scrollTo({ top: 0, behavior: 'auto' });
}

tabs.forEach((t, i) => {
  t.addEventListener('click', () => showTab(t.dataset.tab));
  t.addEventListener('keydown', e => {
    let j = null;
    if (e.key === 'ArrowRight') j = (i + 1) % tabs.length;
    if (e.key === 'ArrowLeft') j = (i - 1 + tabs.length) % tabs.length;
    if (e.key === 'Home') j = 0;
    if (e.key === 'End') j = tabs.length - 1;
    if (j !== null) { e.preventDefault(); showTab(tabs[j].dataset.tab, { focus: true, scroll: false }); }
  });
});
document.addEventListener('click', e => {
  const a = e.target.closest('[data-tab-link]');
  if (!a) return;
  e.preventDefault();
  showTab(a.dataset.tabLink);
});
window.addEventListener('hashchange', () => showTab(location.hash.slice(1)));

function renderNext(id) {
  const nav = document.getElementById('next-link');
  const i = ids.indexOf(id);
  if (i < 0 || i >= ids.length - 1) { nav.innerHTML = ''; return; }
  const nextId = ids[i + 1];
  const h2 = document.querySelector(`#${nextId} h2`);
  const label = h2 ? h2.textContent : tabs.find(t => t.dataset.tab === nextId).textContent;
  nav.innerHTML = `<a href="#${nextId}" data-tab-link="${nextId}"><small>Sigue leyendo</small><b>${label}</b></a>`;
}

/* ---------------- Pirámide de población (SVG propio) ---------------- */
const NS = 'http://www.w3.org/2000/svg';
const PYR_MAX = Math.max(...POP.pyr.flat());

function makePyramid(el, { showYear = true } = {}) {
  const W = 600, rowH = 19, top = showYear ? 78 : 14, groups = 20;
  const H = top + groups * rowH + 34, cx = W / 2, gap = 20, inner = 17, half = cx - inner - 4;
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.setAttribute('role', 'img');
  const title = document.createElementNS(NS, 'title');
  svg.appendChild(title);

  let yearText;
  if (showYear) {
    yearText = document.createElementNS(NS, 'text');
    yearText.setAttribute('class', 'pyr-year');
    yearText.setAttribute('x', 0); yearText.setAttribute('y', 52);
    svg.appendChild(yearText);
  }
  const bars = [];
  for (let g = 0; g < groups; g++) {
    const y = top + (groups - 1 - g) * rowH;
    const cls = g < 3 ? 'y' : g >= 13 ? 'o' : 'a';
    const L = document.createElementNS(NS, 'rect');
    const R = document.createElementNS(NS, 'rect');
    [L, R].forEach(r => { r.setAttribute('y', y + 1.5); r.setAttribute('height', rowH - 3); r.setAttribute('rx', 2); r.setAttribute('class', cls); svg.appendChild(r); });
    bars.push([L, R]);
    if (g % 2 === 0 || g === 19) {
      const t = document.createElementNS(NS, 'text');
      t.setAttribute('x', cx); t.setAttribute('y', y + rowH / 2 + 4); t.setAttribute('text-anchor', 'middle');
      t.textContent = g === 19 ? '95+' : g * 5;
      svg.appendChild(t);
    }
  }
  [['Hombres', cx - gap, 'end'], ['Mujeres', cx + gap, 'start']].forEach(([s, x, a]) => {
    const t = document.createElementNS(NS, 'text');
    t.setAttribute('class', 'pyr-side'); t.setAttribute('x', x); t.setAttribute('y', H - 8); t.setAttribute('text-anchor', a);
    t.textContent = s; svg.appendChild(t);
  });
  el.appendChild(svg);

  function draw(fy) {
    const i0 = Math.floor(fy), i1 = Math.min(i0 + 1, POP.years.length - 1), t = fy - i0;
    const a = POP.pyr[i0], b = POP.pyr[i1];
    for (let g = 0; g < groups; g++) {
      const m = a[g * 2] + (b[g * 2] - a[g * 2]) * t;
      const f = a[g * 2 + 1] + (b[g * 2 + 1] - a[g * 2 + 1]) * t;
      const wm = (m / PYR_MAX) * half, wf = (f / PYR_MAX) * half;
      bars[g][0].setAttribute('x', cx - inner - wm); bars[g][0].setAttribute('width', wm);
      bars[g][1].setAttribute('x', cx + inner); bars[g][1].setAttribute('width', wf);
    }
    const year = POP.years[Math.round(fy)];
    if (yearText) yearText.textContent = year;
    title.textContent = `Pirámide de población de Chile, año ${year}`;
    return year;
  }
  return { draw };
}

function animate(from, to, ms, onFrame, onEnd) {
  const start = performance.now();
  let raf;
  const step = now => {
    const p = Math.min(1, (now - start) / ms);
    const e = p < .5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
    onFrame(from + (to - from) * e);
    if (p < 1) raf = requestAnimationFrame(step); else onEnd && onEnd();
  };
  raf = requestAnimationFrame(step);
  return () => cancelAnimationFrame(raf);
}

// Portada: una sola animación al cargar, 1992 → 2070
const heroPyr = makePyramid(document.getElementById('pyr-hero'));
const lastIdx = POP.years.length - 1;
if (reduceMotion) heroPyr.draw(lastIdx);
else { heroPyr.draw(0); setTimeout(() => animate(0, lastIdx, 6500, f => heroPyr.draw(f)), 500); }

// Explorador de la pestaña "Envejecer de golpe"
const explore = makePyramid(document.getElementById('pyr-explore'), { showYear: false });
const range = document.getElementById('pyr-year');
const out = document.getElementById('pyr-year-out');
const stats = document.getElementById('pyr-stats');
const playBtn = document.getElementById('pyr-play');
let stopAnim = null;

function setYear(fy) {
  const y = explore.draw(fy);
  const i = Math.round(fy);
  range.value = y; out.textContent = y;
  const T = POP.total[i];
  const kids = POP.y0_14[i], old = POP.y65[i], mid = T - kids - old;
  stats.innerHTML =
    `<div><b>${fmt1.format(kids / T * 100)}%</b><span>de 0 a 14 años</span></div>` +
    `<div><b>${fmt1.format(mid / T * 100)}%</b><span>de 15 a 64 años</span></div>` +
    `<div><b>${fmt1.format(old / T * 100)}%</b><span>de 65 años o más</span></div>`;
}
setYear(IDX_2024);
range.addEventListener('input', () => { if (stopAnim) { stopAnim(); stopAnim = null; playBtn.textContent = 'Reproducir'; } setYear(idxOf(+range.value)); });
playBtn.addEventListener('click', () => {
  if (stopAnim) { stopAnim(); stopAnim = null; playBtn.textContent = 'Reproducir'; return; }
  let from = idxOf(+range.value); if (from >= lastIdx) from = 0;
  playBtn.textContent = 'Pausar';
  const ms = reduceMotion ? 1 : (lastIdx - from) * 90;
  stopAnim = animate(from, lastIdx, ms, setYear, () => { stopAnim = null; playBtn.textContent = 'Reproducir'; });
});

/* ---------------- Cunas (Clínica Indisa, −40%) ---------------- */
const crib = cls => `<svg viewBox="0 0 40 32"><path class="${cls}" d="M4 6h3v18h26V6h3v24h-3v-3H7v3H4z M10 12h20v9H10z"/></svg>`;
document.getElementById('cribs').innerHTML = Array.from({ length: 10 }, (_, i) => crib(i < 6 ? 'full' : 'gone')).join('');

/* ---------------- Waffle (salud mental) ---------------- */
// 72,3 / 19,3 / 8,4  → 72 / 19 / 9 puntos (redondeo para sumar 100)
document.getElementById('waffle').innerHTML =
  Array.from({ length: 100 }, (_, i) => `<i class="${i < 72 ? 'down' : i < 91 ? 'same' : 'up'}"></i>`).join('');

/* ---------------- Gráficos (Chart.js) ---------------- */
const charts = {};
const built = new Set();

function css(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }
function palette() {
  return { ink: css('--ink'), muted: css('--muted'), line: css('--line'), amber: css('--amber'),
           peri: css('--peri'), mid: css('--mid'), surface: css('--surface'), amberSoft: css('--amber-soft'), periSoft: css('--peri-soft') };
}

// Línea vertical con etiqueta (marca un año o un hito)
const markerPlugin = {
  id: 'marker',
  afterDatasetsDraw(chart, _a, opts) {
    if (!opts || !opts.lines) return;
    const { ctx, chartArea: { top, bottom }, scales: { x } } = chart;
    opts.lines.forEach(l => {
      const px = x.getPixelForValue(l.index);
      ctx.save();
      ctx.strokeStyle = l.color; ctx.setLineDash([4, 4]); ctx.lineWidth = 1.2;
      if (l.point == null) { ctx.beginPath(); ctx.moveTo(px, top); ctx.lineTo(px, bottom); ctx.stroke(); }
      ctx.setLineDash([]);
      ctx.fillStyle = l.color; ctx.font = '600 12px "Bricolage Grotesque", sans-serif';
      ctx.textAlign = l.align || 'left';
      const dx = l.align === 'right' ? -8 : 8;
      if (l.point != null) {
        const py = chart.scales.y.getPixelForValue(l.point);
        ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();
        ctx.font = '700 13px "Bricolage Grotesque", sans-serif';
        ctx.fillText(l.label, px + dx, py + (l.below ? 22 : -12));
      } else {
        ctx.fillText(l.label, px + dx, top + 14);
      }
      ctx.restore();
    });
  }
};
Chart.register(markerPlugin);

function baseOptions(p) {
  Chart.defaults.font.family = '"Bricolage Grotesque", "Segoe UI", system-ui, sans-serif';
  Chart.defaults.font.size = 12;
  Chart.defaults.color = p.muted;
  return {
    responsive: true, maintainAspectRatio: false,
    animation: reduceMotion ? false : { duration: 700 },
    interaction: { mode: 'index', intersect: false },
    plugins: {
      legend: { labels: { usePointStyle: true, pointStyle: 'circle', boxWidth: 8, boxHeight: 8, color: p.ink, padding: 16 } },
      tooltip: { backgroundColor: p.ink, titleColor: p.surface, bodyColor: p.surface, padding: 10, cornerRadius: 6, displayColors: true, boxPadding: 4 }
    },
    scales: {
      x: { grid: { display: false }, border: { color: p.line }, ticks: { color: p.muted } },
      y: { grid: { color: p.line }, border: { display: false }, ticks: { color: p.muted } }
    }
  };
}
const dashedFuture = { borderDash: ctx => (ctx.p0DataIndex >= IDX_2024 ? [6, 5] : undefined) };
const yearTicks = { callback(v) { const y = POP.years[v]; return y % (window.innerWidth < 600 ? 20 : 10) === 0 ? y : ''; }, autoSkip: false, maxRotation: 0 };

const builders = {
  clinicas: {
    'ch-bebes'(p) {
      const o = baseOptions(p);
      o.plugins.legend.display = false;
      o.scales.x.ticks = { ...o.scales.x.ticks, ...yearTicks };
      o.scales.y.ticks.callback = v => fmt.format(v / 1000) + ' mil';
      o.scales.y.min = 0;
      o.plugins.tooltip.callbacks = { label: c => ' ' + fmt.format(c.raw) + ' niños y niñas de 0 años' };
      o.plugins.marker = { lines: [
        { index: IDX_2024, label: 'Proyección', color: p.muted },
      ] };
      return { type: 'line', options: o, data: { labels: POP.years, datasets: [{
        data: POP.age0, borderColor: p.amber, borderWidth: 3, pointRadius: 0, tension: .25,
        fill: true, backgroundColor: p.amberSoft, segment: dashedFuture
      }] } };
    }
  },
  decidir: {
    'ch-tiempo'(p) {
      const o = baseOptions(p);
      o.indexAxis = 'y';
      o.plugins.legend.display = false;
      o.scales.x = { min: 0, max: 360, grid: { color: p.line }, border: { display: false }, ticks: { stepSize: 60, callback: v => v / 60 + ' h', color: p.muted } };
      o.scales.y = { grid: { display: false }, border: { color: p.line }, ticks: { color: p.ink, font: { size: 14, weight: 600 } } };
      o.plugins.tooltip.callbacks = { label: c => ` ${Math.floor(c.raw / 60)} h ${c.raw % 60} min al día` };
      return { type: 'bar', options: o, data: { labels: ['Mujeres', 'Hombres'], datasets: [{
        data: [297, 172], backgroundColor: [p.amber, p.mid], borderRadius: 6, barThickness: 44
      }] }, plugins: [{
        id: 'barLabels', afterDatasetsDraw(ch) {
          const { ctx } = ch; const meta = ch.getDatasetMeta(0);
          ctx.save(); ctx.font = '700 15px "Bricolage Grotesque", sans-serif'; ctx.fillStyle = p.ink; ctx.textBaseline = 'middle';
          ['4 h 57 min', '2 h 52 min'].forEach((t, i) => ctx.fillText(t, meta.data[i].x + 10, meta.data[i].y));
          ctx.restore();
        }
      }] };
    },
    'ch-costo'(p) {
      return { type: 'doughnut', data: { labels: ['Bienes y servicios', 'Tiempo de cuidado'], datasets: [{
        data: [383267, 211616], backgroundColor: [p.peri, p.amber], borderColor: p.surface, borderWidth: 3, hoverOffset: 6
      }] }, options: {
        responsive: true, maintainAspectRatio: false, cutout: '68%', animation: reduceMotion ? false : { duration: 700 },
        plugins: {
          legend: { display: false },
          tooltip: { backgroundColor: p.ink, titleColor: p.surface, bodyColor: p.surface, callbacks: { label: c => ' ' + money(c.raw) } }
        }
      } };
    },
    'ch-edad'(p) {
      const o = baseOptions(p);
      o.plugins.legend.display = false;
      o.scales.y.ticks.callback = v => '$' + fmt.format(v / 1000) + ' mil';
      o.scales.y.min = 0;
      o.scales.x.ticks = { color: p.ink, font: { size: 13, weight: 600 } };
      o.plugins.tooltip.callbacks = { label: c => ' ' + money(c.raw) + ' al mes' };
      return { type: 'bar', options: o, data: { labels: ['0 años', '2 años', '15 años'], datasets: [{
        data: [735000, 709000, 485000], backgroundColor: [p.amber, p.amber, p.mid], borderRadius: 6, maxBarThickness: 64
      }] } };
    },
    'ch-distrib'(p) {
      const o = baseOptions(p);
      o.indexAxis = 'y';
      o.scales.x = { stacked: true, grid: { color: p.line }, border: { display: false }, ticks: { color: p.muted, callback: v => '$' + fmt.format(v / 1000) + ' mil' } };
      o.scales.y = { stacked: true, grid: { display: false }, border: { color: p.line }, ticks: { color: p.ink, font: { size: 13, weight: 600 } } };
      o.plugins.tooltip.callbacks = { label: c => ` ${c.dataset.label}: ${money(c.raw)}` };
      return { type: 'bar', options: o, data: { labels: ['0 años', '14 a 17 años'], datasets: [
        { label: 'Tiempo de cuidado', data: [369000, 68000], backgroundColor: p.amber, borderRadius: 4, barThickness: 40 },
        { label: 'Bienes y servicios', data: [366000, 418000], backgroundColor: p.peri, borderRadius: 4, barThickness: 40 }
      ] } };
    }
  },
  envejecer: {
    'ch-comunas'(p) {
      const o = baseOptions(p);
      o.indexAxis = 'y';
      o.plugins.legend.display = false;
      o.scales.x = { min: -10, max: 0, grid: { color: p.line }, border: { display: false }, ticks: { color: p.muted, callback: v => fmt.format(v) } };
      o.scales.y = { grid: { display: false }, border: { color: p.ink }, position: 'right', ticks: { color: p.ink, font: { size: 13, weight: 600 } } };
      o.plugins.tooltip.callbacks = { label: c => ` ${fmt1.format(c.raw)} por cada mil habitantes` };
      return { type: 'bar', options: o, data: {
        labels: ['Cochamó (Los Lagos)', 'Portezuelo (Ñuble)', 'Río Hurtado (Coquimbo)'],
        datasets: [{ data: [-8.6, -7.0, -5.9], backgroundColor: p.peri, borderRadius: 4, barThickness: 34 }]
      } };
    },
    'ch-cruce'(p) {
      const o = baseOptions(p);
      const cross = POP.y65.findIndex((v, i) => v > POP.y0_14[i]);
      o.scales.x.ticks = { ...o.scales.x.ticks, ...yearTicks };
      o.scales.y.ticks.callback = v => fmt.format(v / 1e6) + ' M';
      o.scales.y.min = 0;
      o.plugins.tooltip.callbacks = { label: c => ` ${c.dataset.label}: ${fmt1.format(c.raw / 1e6)} millones` };
      o.plugins.marker = { lines: [
        { index: IDX_2024, label: 'Proyección', color: p.muted },
        { index: cross, label: `${POP.years[cross]}: se cruzan`, color: p.ink, point: POP.y65[cross], below: true }
      ] };
      return { type: 'line', options: o, data: { labels: POP.years, datasets: [
        { label: '0 a 14 años', data: POP.y0_14, borderColor: p.amber, backgroundColor: p.amber, borderWidth: 3, pointRadius: 0, tension: .25, segment: dashedFuture },
        { label: '65 años o más', data: POP.y65, borderColor: p.peri, backgroundColor: p.peri, borderWidth: 3, pointRadius: 0, tension: .25, segment: dashedFuture }
      ] } };
    }
  },
  vejez: {
    'ch-sentir'(p) {
      const o = baseOptions(p);
      o.indexAxis = 'y';
      o.plugins.legend.display = false;
      o.scales.x = { min: 0, max: 40, grid: { color: p.line }, border: { display: false }, ticks: { color: p.muted, callback: v => v + '%' } };
      o.scales.y = { grid: { display: false }, border: { color: p.line }, ticks: { color: p.ink, font: { size: 13, weight: 600 } } };
      o.plugins.tooltip.callbacks = { label: c => ` ${fmt1.format(c.raw)}%` };
      return { type: 'bar', options: o, data: { labels: ['Miedo', 'Tranquilidad', 'Intranquilidad o tristeza'], datasets: [{
        data: [35.3, 29.8, 19.1], backgroundColor: [p.peri, p.mid, p.peri], borderRadius: 4, barThickness: 32
      }] } };
    }
  },
  politicas: {
    'ch-total'(p) {
      const o = baseOptions(p);
      const peak = POP.total.indexOf(Math.max(...POP.total));
      o.plugins.legend.display = false;
      o.scales.x.ticks = { ...o.scales.x.ticks, ...yearTicks };
      o.scales.y.ticks.callback = v => fmt.format(v / 1e6) + ' M';
      o.scales.y.min = 12e6;
      o.plugins.tooltip.callbacks = { label: c => ` ${fmt1.format(c.raw / 1e6)} millones de personas` };
      o.plugins.marker = { lines: [
        { index: IDX_2024, label: 'Proyección', color: p.muted, align: 'right' },
        { index: peak, label: `Máximo en ${POP.years[peak]}: ${fmt1.format(POP.total[peak] / 1e6)} M`, color: p.ink, point: POP.total[peak] }
      ] };
      return { type: 'line', options: o, data: { labels: POP.years, datasets: [{
        data: POP.total, borderColor: p.ink, borderWidth: 3, pointRadius: 0, tension: .25,
        fill: true, backgroundColor: p.periSoft, segment: dashedFuture
      }] } };
    }
  }
};

function initCharts(panelId) {
  if (built.has(panelId) || !builders[panelId] || typeof Chart === 'undefined') return;
  built.add(panelId);
  const p = palette();
  Object.entries(builders[panelId]).forEach(([id, make]) => {
    const el = document.getElementById(id);
    if (el) charts[id] = new Chart(el, make(p));
  });
}

// Si cambia el modo claro/oscuro del sistema, se redibujan los gráficos con los nuevos colores
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
  Object.values(charts).forEach(c => c.destroy());
  Object.keys(charts).forEach(k => delete charts[k]);
  const visible = panels.find(p => !p.hidden);
  built.clear();
  if (visible) initCharts(visible.id);
});

/* =========================================================
   JUEGO 1: Dibuja el futuro de Chile
   La persona traza su estimación 2025-2070 y luego se revela
   la proyección del INE (mismos datos de POP).
   ========================================================= */
(function drawGame() {
  const svg = document.getElementById('draw-svg');
  if (!svg) return;
  const N = POP.years.length, LAST = N - 1, START = IDX_2024;
  let W = 720, H = 400, M = { l: 54, r: 70, t: 22, b: 38 };
  let narrow = false;
  const fmtM = v => fmt1.format(v / 1e6);

  const ROUNDS = [
    {
      key: 'y0_14', short: 'Niños', color: 'var(--amber)', min: 0, max: 6e6, step: 1e6,
      q: '¿Cuántos niños y niñas menores de 15 años habrá en Chile?',
      text: s => `Según el INE, en 2070 habría unos <b>${fmtM(s[LAST])} millones</b> de menores de 15 años, alrededor de un tercio de los ${fmtM(s[START])} millones que había en 2024. Es la consecuencia directa de una fecundidad de 0,99 hijos por mujer, la mitad de lo necesario para el reemplazo generacional.`
    },
    {
      key: 'y65', short: 'Personas mayores', color: 'var(--peri)', min: 0, max: 10e6, step: 2e6,
      q: '¿Cuántas personas de 65 años o más vivirán en Chile?',
      text: s => `Las personas de 65 años o más pasarían de ${fmtM(s[START])} millones en 2024 a <b>${fmtM(s[LAST])} millones</b> en 2070. Desde 2028 ya serían más que los menores de 15 años, y en 2070 representarían más de 4 de cada 10 habitantes.`
    },
    {
      key: 'total', short: 'Población total', color: 'var(--ink)', min: 10e6, max: 26e6, step: 2e6,
      q: '¿Cuántas personas vivirán en Chile en total?',
      text: s => {
        const peak = s.indexOf(Math.max(...s));
        return `La población seguiría creciendo hasta ${POP.years[peak]}, cuando alcanzaría su máximo de ${fmtM(s[peak])} millones. Desde entonces empezaría a disminuir: en 2070 Chile tendría unos <b>${fmtM(s[LAST])} millones</b> de habitantes, menos que hoy.`;
      }
    }
  ];

  const state = ROUNDS.map(r => ({ guess: [], last: START, revealed: false }));
  let round = 0, drawing = false, prev = null;

  const qEl = document.getElementById('draw-q');
  const helpEl = document.getElementById('draw-help');
  const revealBtn = document.getElementById('draw-reveal');
  const resetBtn = document.getElementById('draw-reset');
  const range = document.getElementById('draw-range');
  const rangeOut = document.getElementById('draw-range-out');
  const result = document.getElementById('draw-result');

  const R = () => ROUNDS[round];
  const S = () => state[round];
  const series = () => POP[R().key];
  const x = i => M.l + (i / LAST) * (W - M.l - M.r);
  const y = v => M.t + (1 - (v - R().min) / (R().max - R().min)) * (H - M.t - M.b);
  const invX = px => Math.round(((px - M.l) / (W - M.l - M.r)) * LAST);
  const invY = py => R().min + (1 - (py - M.t) / (H - M.t - M.b)) * (R().max - R().min);
  const clampV = v => Math.max(R().min, Math.min(R().max, v));
  const el = (tag, attrs = {}, text) => {
    const n = document.createElementNS(NS, tag);
    Object.entries(attrs).forEach(([k, v]) => n.setAttribute(k, v));
    if (text != null) n.textContent = text;
    return n;
  };
  const pathFor = (vals, from, to) => {
    let d = '';
    for (let i = from; i <= to; i++) d += (i === from ? 'M' : 'L') + x(i).toFixed(1) + ',' + y(vals[i]).toFixed(1);
    return d;
  };

  let minePath, handle;

  function build() {
    const r = R(), s = series(), st = S();
    narrow = window.innerWidth < 600;
    if (narrow) { W = 400; H = 340; M = { l: 44, r: 36, t: 16, b: 32 }; }
    else { W = 720; H = 400; M = { l: 54, r: 70, t: 22, b: 38 }; }
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.replaceChildren();
    svg.classList.toggle('is-locked', st.revealed);
    svg.appendChild(el('rect', { class: 'zone', x: x(START), y: M.t, width: x(LAST) - x(START), height: H - M.t - M.b }));
    for (let v = r.min; v <= r.max + 1; v += r.step) {
      svg.appendChild(el('line', { class: 'grid', x1: M.l, x2: x(LAST), y1: y(v), y2: y(v) }));
      svg.appendChild(el('text', { x: M.l - 8, y: y(v) + 4, 'text-anchor': 'end' }, fmt.format(v / 1e6) + ' M'));
    }
    (narrow ? [1992, 2024, 2050, 2070] : [1992, 2000, 2010, 2020, 2030, 2040, 2050, 2060, 2070]).forEach(yr => {
      svg.appendChild(el('text', { x: x(idxOf(yr)), y: H - 12, 'text-anchor': 'middle' }, yr));
    });
    if (st.last === START && !st.revealed) {
      svg.appendChild(el('text', { class: 'zone-label', x: (x(START) + x(LAST)) / 2, y: M.t + 30, 'text-anchor': 'middle' }, 'Dibuja aquí tu estimación'));
    }
    svg.appendChild(el('path', { class: 'known', d: pathFor(s, 0, START) }));
    minePath = el('path', { class: 'mine' });
    svg.appendChild(minePath);
    handle = el('g');
    handle.appendChild(el('circle', { class: 'handle-ring', cx: x(START), cy: y(s[START]), r: 13 }));
    handle.appendChild(el('circle', { class: 'handle', cx: x(START), cy: y(s[START]), r: 7 }));
    svg.appendChild(handle);
    updateMine();
    if (st.revealed) drawReal(false);
  }

  function updateMine() {
    const st = S();
    st.guess[START] = series()[START];
    minePath.setAttribute('d', st.last > START ? pathFor(st.guess, START, st.last) : '');
    revealBtn.disabled = st.revealed || st.last < LAST;
    resetBtn.disabled = st.revealed || st.last === START;
    range.disabled = st.revealed;
    document.querySelector('.draw-alt').hidden = st.revealed;
    document.querySelector('.draw-actions').hidden = st.revealed;
    if (st.last === LAST) { range.value = st.guess[LAST]; rangeOut.textContent = fmtM(st.guess[LAST]) + ' M'; }
  }

  function setPoint(i, v) {
    const st = S();
    i = Math.max(START + 1, Math.min(LAST, i));
    if (i >= LAST - 2) i = LAST; // tolerancia al llegar al borde
    v = clampV(v);
    if (i > st.last) {
      const v0 = st.guess[st.last];
      for (let k = st.last + 1; k <= i; k++) st.guess[k] = v0 + (v - v0) * (k - st.last) / (i - st.last);
      st.last = i;
    } else if (prev && prev.i !== i) {
      const a = Math.min(prev.i, i), b = Math.max(prev.i, i);
      const va = a === i ? v : prev.v, vb = b === i ? v : prev.v;
      for (let k = a; k <= b; k++) st.guess[k] = va + (vb - va) * (k - a) / (b - a || 1);
    } else {
      st.guess[i] = v;
    }
    prev = { i, v };
    const lbl = svg.querySelector('.zone-label'); if (lbl) lbl.remove();
    updateMine();
  }

  function svgPoint(e) {
    const p = svg.createSVGPoint(); p.x = e.clientX; p.y = e.clientY;
    return p.matrixTransform(svg.getScreenCTM().inverse());
  }
  svg.addEventListener('pointerdown', e => {
    if (S().revealed) return;
    drawing = true; prev = null;
    svg.setPointerCapture(e.pointerId);
    const p = svgPoint(e); setPoint(invX(p.x), invY(p.y));
  });
  svg.addEventListener('pointermove', e => {
    if (!drawing) return;
    const p = svgPoint(e); setPoint(invX(p.x), invY(p.y));
  });
  ['pointerup', 'pointercancel'].forEach(t => svg.addEventListener(t, () => { drawing = false; prev = null; }));

  // Alternativa accesible: elegir el valor de 2070 y unir con una recta
  range.addEventListener('input', () => {
    const st = S(), v0 = series()[START], v = +range.value;
    for (let k = START + 1; k <= LAST; k++) st.guess[k] = v0 + (v - v0) * (k - START) / (LAST - START);
    st.last = LAST;
    const lbl = svg.querySelector('.zone-label'); if (lbl) lbl.remove();
    updateMine();
  });

  resetBtn.addEventListener('click', () => { S().guess = []; S().last = START; build(); setupRange(); });

  function tag(text, px, py, color) {
    const g = el('g');
    const t = el('text', { class: 'tag', x: px + 10, y: py + 4 }, text);
    t.style.fill = color;
    g.appendChild(t);
    return g;
  }

  function drawReal(animated) {
    const s = series(), st = S(), r = R();
    const real = el('path', { class: 'real', d: pathFor(s, START, LAST) });
    real.style.stroke = r.color;
    svg.insertBefore(real, handle);
    if (animated && !reduceMotion) {
      const len = real.getTotalLength();
      real.style.strokeDasharray = len; real.style.strokeDashoffset = len;
      real.getBoundingClientRect();
      real.style.transition = 'stroke-dashoffset 1.6s ease-in-out';
      real.style.strokeDashoffset = 0;
    }
    // Etiquetas al final de cada línea, separadas si quedan muy juntas
    let yReal = y(s[LAST]), yMine = y(st.guess[LAST]);
    if (Math.abs(yReal - yMine) < 18) { const mid = (yReal + yMine) / 2; yReal = mid + (s[LAST] >= st.guess[LAST] ? -10 : 10); yMine = mid + (s[LAST] >= st.guess[LAST] ? 10 : -10); }
    svg.appendChild(tag('INE', x(LAST), yReal, r.color));
    svg.appendChild(tag('Tú', x(LAST), yMine, 'var(--muted)'));
  }

  function showResult() {
    const s = series(), st = S(), r = R();
    const mine = st.guess[LAST], real = s[LAST];
    const diff = (mine - real) / real;
    const diffText = Math.abs(diff) < 0.1
      ? 'Tu línea quedó muy cerca de la proyección del INE para 2070.'
      : `Tu estimación para 2070 quedó un ${fmt.format(Math.round(Math.abs(diff) * 100))}% ${diff > 0 ? 'por encima' : 'por debajo'} de la proyección del INE.`;
    const next = round < ROUNDS.length - 1
      ? `<button type="button" class="btn" data-draw-next>Siguiente: ${ROUNDS[round + 1].short.toLowerCase()}</button>`
      : `<p>Estos cambios no dependen de una sola decisión: ya están en marcha. <a href="#envejecer" data-tab-link="envejecer">Lee cómo afectan a la salud, la educación y las pensiones en «Envejecer de golpe»</a>.</p>
         <button type="button" class="btn btn--ghost" data-draw-restart>Volver a jugar</button>`;
    result.innerHTML = `
      <div class="compare">
        <div><b>${fmtM(s[START])} M</b><span>En 2024</span></div>
        <div><b>${fmtM(mine)} M</b><span>Tu estimación para 2070</span></div>
        <div class="is-real" style="border-color:${r.color}"><b>${fmtM(real)} M</b><span>Proyección del INE para 2070</span></div>
      </div>
      <p>${diffText}</p>
      <p>${r.text(s)}</p>
      ${next}`;
    result.hidden = false;
  }

  revealBtn.addEventListener('click', () => {
    const st = S();
    if (st.last < LAST) return;
    st.revealed = true;
    svg.classList.add('is-locked');
    updateMine();
    drawReal(true);
    showResult();
    helpEl.textContent = 'La línea punteada es tu estimación; la línea de color es la proyección del INE.';
  });

  result.addEventListener('click', e => {
    if (e.target.closest('[data-draw-next]')) goRound(round + 1);
    if (e.target.closest('[data-draw-restart]')) {
      state.forEach(st => { st.guess = []; st.last = START; st.revealed = false; });
      goRound(0);
    }
  });

  function setupRange() {
    const r = R(), st = S();
    range.min = r.min; range.max = r.max; range.step = (r.max - r.min) / 320;
    range.value = st.last === LAST ? st.guess[LAST] : series()[START];
    range.setAttribute('aria-valuetext', fmtM(+range.value) + ' millones');
    rangeOut.textContent = st.last === LAST ? fmtM(st.guess[LAST]) + ' M' : '';
  }
  range.addEventListener('input', () => range.setAttribute('aria-valuetext', fmtM(+range.value) + ' millones'));

  function goRound(i) {
    round = i;
    qEl.textContent = R().q;
    helpEl.textContent = S().revealed
      ? 'La línea punteada es tu estimación; la línea de color es la proyección del INE.'
      : 'Los datos hasta 2024 ya están en el gráfico. Arrastra desde el punto hasta el borde derecho para dibujar lo que crees que pasará hasta 2070.';
    build(); setupRange();
    if (S().revealed) showResult(); else { result.hidden = true; result.innerHTML = ''; }
  }
  let lastNarrow = window.innerWidth < 600;
  window.addEventListener('resize', () => {
    const n = window.innerWidth < 600;
    if (n !== lastNarrow) { lastNarrow = n; build(); }
  });
  goRound(0);
})();

/* =========================================================
   JUEGO 2: ¿Mito o realidad? sobre la vejez
   Cada respuesta se apoya en las fuentes del reportaje.
   Para editar: cambien el texto de ITEMS (s = afirmación,
   a = 'mito' o 'realidad', e = explicación, src = fuente).
   ========================================================= */
(function mythGame() {
  const ITEMS = [
    { s: 'Perder los dientes es una parte normal e inevitable del envejecimiento.', a: 'mito',
      e: 'La odontogeriatra Soraya León explica que en Chile persiste el mito cultural de normalizar la pérdida de piezas dentales, cuando en realidad se trata de un proceso patológico que se puede prevenir.',
      src: 'Soraya León, odontogeriatra, Universidad de Talca' },
    { s: 'A los 60 años, el GES cubre una atención odontológica integral que puede incluir prótesis dentales.', a: 'realidad',
      e: 'Es una garantía del Plan AUGE/GES con una canasta amplia de prestaciones, pero caduca al cumplir 61 años. Según Viviana García, mucha gente la pierde porque no sabe que existe.',
      src: 'Viviana García, directora ejecutiva del Centro Gerópolis, U. de Valparaíso' },
    { s: 'La mayoría de las personas mayores no logra valerse por sí misma.', a: 'mito',
      e: 'El 58,7% de los encuestados lo cree, pero la psicogerontóloga Mijal Martínez advierte que esta percepción contrasta con la realidad funcional de las personas mayores, y que asumirla puede acelerar la pérdida de autonomía.',
      src: '8ª Encuesta de Inclusión y Exclusión Social de las Personas Mayores (2025) y Mijal Martínez, psicogerontóloga' },
    { s: 'Vivir más años significa también vivir más años con buena salud.', a: 'mito',
      e: 'En Chile existe una brecha cercana a una década entre la esperanza de vida y la esperanza de vida saludable: en promedio, los últimos 10 años de vida se viven en malas condiciones de salud.',
      src: 'Viviana García, Centro Gerópolis' },
    { s: 'Perder la dentadura puede llevar a una persona mayor al aislamiento e incluso a la depresión.', a: 'realidad',
      e: 'El daño no se limita a la dificultad para masticar. Afecta la autoestima y la confianza para salir: las personas se aíslan, dejan de hacer vida social y eso puede derivar en depresión.',
      src: 'Soraya León, odontogeriatra, Universidad de Talca' },
    { s: 'Sobreproteger a las personas mayores ayuda a cuidar su autonomía.', a: 'mito',
      e: 'Según Mijal Martínez, la sobreprotección y la falta de espacios terminan por mermar la autonomía y acelerar el deterioro emocional.',
      src: 'Mijal Martínez, psicóloga especialista en psicogerontología' },
    { s: 'Las personas mayores están entre los principales usuarios de la atención primaria de salud.', a: 'realidad',
      e: 'Así es, aunque, como advierte Viviana García, hay pocos recursos destinados específicamente a ellas. Por eso plantea una reorientación de recursos hacia la población mayor.',
      src: 'Viviana García, Centro Gerópolis' },
    { s: 'La mayoría de las personas cree que la satisfacción con la vida aumenta al envejecer.', a: 'mito',
      e: 'Ocurre lo contrario: el 72,3% considera que la satisfacción con la vida disminuye al envejecer, el 19,3% cree que se mantiene y solo el 8,4% estima que aumenta.',
      src: '8ª Encuesta de Inclusión y Exclusión Social de las Personas Mayores en Chile (2025)' },
    { s: 'Al pensar en su propia vejez, el sentimiento más frecuente de las personas es el miedo.', a: 'realidad',
      e: 'El miedo es el sentimiento predominante (35,3%), seguido de la tranquilidad (29,8%) y la intranquilidad o tristeza (19,1%). Además, el 42,1% proyecta que su vejez será peor que sus años previos.',
      src: '8ª Encuesta de Inclusión y Exclusión Social de las Personas Mayores en Chile (2025)' },
    { s: 'Prepararse para llegar sano a la vejez es algo que conviene empezar a pensar a partir de los 60 años.', a: 'mito',
      e: 'Viviana García plantea una mirada de curso de vida: educación y empoderamiento en salud para que las personas inviertan en su cuidado desde temprana edad y no lleguen a la vejez en malas condiciones.',
      src: 'Viviana García, Centro Gerópolis' }
  ];

  const card = document.getElementById('myth-card');
  if (!card) return;
  const progress = document.getElementById('myth-progress');
  const count = document.getElementById('myth-count');
  const statement = document.getElementById('myth-statement');
  const buttons = [...document.querySelectorAll('.myth-btn')];
  const answer = document.getElementById('myth-answer');
  const end = document.getElementById('myth-end');
  let i = 0, matches = 0;

  statement.tabIndex = -1;

  function render() {
    const it = ITEMS[i];
    progress.innerHTML = ITEMS.map((_, k) => `<i class="${k < i ? 'is-done' : k === i ? 'is-current' : ''}"></i>`).join('');
    count.textContent = `Afirmación ${i + 1} de ${ITEMS.length}`;
    statement.textContent = it.s;
    buttons.forEach(b => { b.disabled = false; b.classList.remove('is-chosen'); b.removeAttribute('aria-pressed'); });
    answer.hidden = true; answer.innerHTML = '';
  }

  buttons.forEach(b => b.addEventListener('click', () => {
    const it = ITEMS[i], chosen = b.dataset.answer, ok = chosen === it.a;
    if (ok) matches++;
    buttons.forEach(x => { x.disabled = true; });
    b.classList.add('is-chosen'); b.setAttribute('aria-pressed', 'true');
    const last = i === ITEMS.length - 1;
    answer.innerHTML = `
      <p class="myth-verdict" tabindex="-1">${it.a === 'mito' ? 'Es un mito.' : 'Es realidad.'}</p>
      <p class="myth-match">${ok ? 'Coincide con tu respuesta.' : `Tu respuesta fue «${chosen === 'mito' ? 'Mito' : 'Realidad'}».`}</p>
      <p class="myth-expl">${it.e}</p>
      <p class="myth-src">Fuente: ${it.src}</p>
      <button type="button" class="btn" data-myth-next>${last ? 'Ver el cierre' : 'Siguiente afirmación'}</button>`;
    answer.style.borderLeftColor = it.a === 'mito' ? 'var(--peri)' : 'var(--amber)';
    answer.hidden = false;
    answer.querySelector('.myth-verdict').focus({ preventScroll: true });
  }));

  answer.addEventListener('click', e => {
    if (!e.target.closest('[data-myth-next]')) return;
    if (i < ITEMS.length - 1) { i++; render(); statement.focus({ preventScroll: true }); }
    else finish();
  });

  function finish() {
    card.hidden = true;
    end.innerHTML = `
      <h3 tabindex="-1">Coincidiste con las fuentes en ${matches} de ${ITEMS.length} afirmaciones.</h3>
      <p>Muchas de estas ideas están muy instaladas: el 72,3% de las personas encuestadas cree que la satisfacción con la vida disminuye al envejecer, y el 58,7% piensa que la mayoría de las personas mayores no logra valerse por sí misma.</p>
      <p>Esas creencias no son inofensivas. Según la psicogerontóloga Mijal Martínez, las personas mayores pueden terminar internalizándolas, como una profecía autocumplida que reduce su autonomía y sus proyectos.</p>
      <div class="draw-actions">
        <a class="btn" href="#vejez" data-tab-link="vejez">Leer «La vejez en silencio»</a>
        <button type="button" class="btn btn--ghost" data-myth-restart>Volver a jugar</button>
      </div>`;
    end.hidden = false;
    end.querySelector('h3').focus({ preventScroll: true });
  }
  end.addEventListener('click', e => {
    if (!e.target.closest('[data-myth-restart]')) return;
    i = 0; matches = 0; end.hidden = true; card.hidden = false; render(); statement.focus({ preventScroll: true });
  });

  render();
})();

