/* =========================================================
   Reproductores de video y audio
   Se construyen cuando se abre la pestaña donde están, así el
   sitio no descarga todos los archivos de una vez.
   ========================================================= */
const mediaEls = new Set();
function pauseAll(except) { mediaEls.forEach(m => { if (m !== except && !m.paused) m.pause(); }); }

const ICON = {
  play: '<svg class="ic-play" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4.6v14.8a1 1 0 0 0 1.5.86l12-7.4a1 1 0 0 0 0-1.72l-12-7.4A1 1 0 0 0 7 4.6z"/></svg>',
  pause: '<svg class="ic-pause" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="6" y="4.5" width="4.2" height="15" rx="1.2"/><rect x="13.8" y="4.5" width="4.2" height="15" rx="1.2"/></svg>',
  volOn: '<svg class="ic-vol-on" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9.5v5h3.5L12 18.5v-13L7.5 9.5H4z" fill="currentColor" stroke="none"/><path d="M15.5 9a4.2 4.2 0 0 1 0 6M18 6.5a8 8 0 0 1 0 11"/></svg>',
  volOff: '<svg class="ic-vol-off" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9.5v5h3.5L12 18.5v-13L7.5 9.5H4z" fill="currentColor" stroke="none"/><path d="M16 9.5l5 5M21 9.5l-5 5"/></svg>',
  full: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>',
  video: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="6" width="13" height="12" rx="2"/><path d="M16 10.5l5-3v9l-5-3z"/></svg>',
  mic: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5.5 11.5a6.5 6.5 0 0 0 13 0M12 18v3"/></svg>'
};
const esc = t => String(t).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmtTime = s => (isFinite(s) && s >= 0) ? Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0') : '–:––';
const SPEEDS = [1, 1.25, 1.5, 2, 0.75];

// Barras decorativas de la onda: siempre iguales para un mismo audio
function waveHeights(seedText, n) {
  let h = 2166136261;
  for (const ch of seedText) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  const rnd = () => { h += 0x6D2B79F5; let t = h; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const phase = rnd() * 6;
  return Array.from({ length: n }, (_, i) => {
    const env = 0.55 + 0.35 * Math.sin(i / 5 + phase) * Math.sin(i / 13 + phase * 2);
    return Math.round(Math.max(14, Math.min(100, (env * 0.7 + rnd() * 0.5) * 100)));
  });
}

function playerHTML(key, m) {
  const isVideo = m.type === 'video';
  const initials = m.who.split(' ').filter(Boolean).map(w => w[0]).slice(0, 2).join('').toUpperCase();
  const speedBtn = '<button type="button" class="pl-speed" data-act="speed" aria-label="Velocidad de reproducción">1×</button>';
  const muteBtn = `<button type="button" class="pl-btn" data-act="mute" aria-label="Silenciar">${ICON.volOn}${ICON.volOff}</button>`;
  const head = `
    <div class="pl-head">
      ${isVideo ? '' : `<div class="pl-av">${m.photo ? `<img src="${esc(m.photo)}" alt="">` : esc(initials)}</div>`}
      <div class="pl-who"><b>${esc(m.who)}</b><span>${esc(m.role)}</span></div>
      <span class="pl-kind">${isVideo ? ICON.video : ICON.mic}<span>${isVideo ? 'Video' : 'Audio'}</span></span>
    </div>`;
  const msg = `<p class="pl-msg">No se pudo cargar ${isVideo ? 'el video' : 'el audio'}. Revisa tu conexión o <a href="${esc(m.src)}" target="_blank" rel="noopener">ábrelo en una pestaña nueva</a>.</p>`;
  if (isVideo) {
    return `
    <div class="pl pl-video" data-key="${key}">
      ${head}
      <div class="pl-stage">
        <div class="pl-frame" tabindex="0" role="group" aria-label="Video de ${esc(m.who)}">
          <video playsinline preload="metadata" src="${esc(m.src)}#t=0.1"></video>
          <button type="button" class="pl-big" data-act="play" aria-label="Reproducir video de ${esc(m.who)}">${ICON.play}</button>
        </div>
      </div>
      ${msg}
      <div class="pl-bar">
        <input class="pl-seek" type="range" min="0" max="1000" step="1" value="0" aria-label="Avance del video">
        <div class="pl-ctrl">
          <button type="button" class="pl-btn pl-btn--play" data-act="play" aria-label="Reproducir">${ICON.play}${ICON.pause}</button>
          <span class="pl-time" aria-live="off">0:00 / –:––</span>
          ${speedBtn}${muteBtn}
          <button type="button" class="pl-btn" data-act="full" aria-label="Pantalla completa">${ICON.full}</button>
        </div>
      </div>
    </div>`;
  }
  const bars = waveHeights(key + m.who, 64).map(h => `<i style="height:${h}%"></i>`).join('');
  return `
    <div class="pl pl-audio" data-key="${key}">
      ${head}
      <audio preload="metadata" src="${esc(m.src)}"></audio>
      ${msg}
      <div class="pl-audio-row">
        <button type="button" class="pl-btn pl-btn--play" data-act="play" aria-label="Reproducir audio de ${esc(m.who)}">${ICON.play}${ICON.pause}</button>
        <div class="pl-wave">${bars}<input class="pl-seek" type="range" min="0" max="1000" step="10" value="0" aria-label="Avance del audio"></div>
      </div>
      <div class="pl-bar">
        <div class="pl-ctrl">
          <span class="pl-time" aria-live="off">0:00 / –:––</span>
          ${speedBtn}${muteBtn}
        </div>
      </div>
    </div>`;
}

function wirePlayer(root, m) {
  const media = root.querySelector('video, audio');
  const seek = root.querySelector('.pl-seek');
  const time = root.querySelector('.pl-time');
  const speed = root.querySelector('[data-act="speed"]');
  const frame = root.querySelector('.pl-frame');
  const bars = [...root.querySelectorAll('.pl-wave i')];
  const playBtns = [...root.querySelectorAll('[data-act="play"]')];
  const fullBtn = root.querySelector('[data-act="full"]');
  let raf = 0, lastOn = -1, si = 0;
  mediaEls.add(media);

  function paint() {
    const d = media.duration, t = media.currentTime;
    const p = d > 0 ? Math.min(1, t / d) : 0;
    if (document.activeElement !== seek || !seek.matches(':active')) seek.value = Math.round(p * 1000);
    seek.style.setProperty('--p', (p * 100).toFixed(2) + '%');
    time.textContent = fmtTime(t) + ' / ' + fmtTime(d);
    if (bars.length) {
      const on = Math.round(p * bars.length);
      if (on !== lastOn) { bars.forEach((b, i) => b.classList.toggle('on', i < on)); lastOn = on; }
    }
  }
  const loop = () => { paint(); raf = requestAnimationFrame(loop); };
  const toggle = () => {
    if (media.paused) { const pr = media.play(); if (pr && pr.catch) pr.catch(() => {}); } else media.pause();
  };

  media.addEventListener('play', () => {
    pauseAll(media);
    root.classList.add('is-playing');
    playBtns.forEach(b => b.setAttribute('aria-label', 'Pausar'));
    cancelAnimationFrame(raf); raf = requestAnimationFrame(loop);
  });
  const stopped = () => {
    root.classList.remove('is-playing');
    playBtns.forEach(b => b.setAttribute('aria-label', 'Reproducir'));
    cancelAnimationFrame(raf); paint();
  };
  media.addEventListener('pause', stopped);
  media.addEventListener('ended', stopped);
  media.addEventListener('loadedmetadata', () => {
    if (frame && media.videoWidth) frame.style.setProperty('--ar', (media.videoWidth / media.videoHeight).toFixed(4));
    paint();
  });
  media.addEventListener('durationchange', paint);
  media.addEventListener('seeked', paint);
  media.addEventListener('timeupdate', () => { if (media.paused) paint(); });
  media.addEventListener('error', () => root.classList.add('has-error'));

  seek.addEventListener('input', () => {
    if (media.duration > 0) { media.currentTime = (seek.value / 1000) * media.duration; paint(); }
  });
  root.querySelectorAll('[data-act="play"]').forEach(b => b.addEventListener('click', e => { e.stopPropagation(); toggle(); }));
  if (frame) frame.addEventListener('click', e => { if (!e.target.closest('button')) toggle(); });

  speed.addEventListener('click', () => {
    si = (si + 1) % SPEEDS.length;
    media.playbackRate = SPEEDS[si];
    speed.textContent = String(SPEEDS[si]).replace('.', ',') + '×';
  });
  root.querySelector('[data-act="mute"]').addEventListener('click', e => {
    media.muted = !media.muted;
    root.classList.toggle('is-muted', media.muted);
    e.currentTarget.setAttribute('aria-label', media.muted ? 'Activar sonido' : 'Silenciar');
  });

  if (fullBtn) {
    const canFull = root.requestFullscreen || root.webkitRequestFullscreen || media.webkitEnterFullscreen;
    if (!canFull) fullBtn.hidden = true;
    fullBtn.addEventListener('click', () => {
      if (document.fullscreenElement) { document.exitFullscreen(); return; }
      if (root.requestFullscreen) root.requestFullscreen().catch(() => {});
      else if (root.webkitRequestFullscreen) root.webkitRequestFullscreen();
      else if (media.webkitEnterFullscreen) media.webkitEnterFullscreen();
    });
  }

  // Teclado sobre el video: espacio o K = reproducir, flechas = ±5 s, M = silenciar, F = pantalla completa
  if (frame) frame.addEventListener('keydown', e => {
    const k = e.key.toLowerCase();
    if (k === ' ' || k === 'k') { e.preventDefault(); toggle(); }
    else if (k === 'arrowright') { e.preventDefault(); media.currentTime = Math.min(media.duration || 0, media.currentTime + 5); }
    else if (k === 'arrowleft') { e.preventDefault(); media.currentTime = Math.max(0, media.currentTime - 5); }
    else if (k === 'm') root.querySelector('[data-act="mute"]').click();
    else if (k === 'f' && fullBtn && !fullBtn.hidden) fullBtn.click();
  });
  paint();
}

function initPlayers(panelId) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  panel.querySelectorAll('.player[data-player]').forEach(host => {
    if (host.dataset.ready) return;
    const key = host.dataset.player, m = MEDIA[key];
    if (!m) { console.warn('Reproductor sin datos en MEDIA:', key); return; }
    host.dataset.ready = '1';
    host.innerHTML = playerHTML(key, m);
    wirePlayer(host.querySelector('.pl'), m);
  });
}

